<?php use App\Support\App;App::requireAdmin();$title='Admin Settings';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><h1 class="page-title">Settings</h1><p class="page-sub">Konfigurasi website dan metode pembayaran.</p><form id="f" class="grid lg:grid-cols-2 gap-5 mt-6"><section class="saas-card p-5 sm:p-6"><h2 class="font-semibold">General</h2><p class="text-sm text-zinc-500 mt-1">Identitas utama platform.</p><label class="block text-sm font-semibold mt-5">Site name</label><input class="field mt-2" name="site_name" value="<?=htmlspecialchars(App::setting('site_name','CEKSINYAL'))?>"></section><section class="saas-card p-5 sm:p-6"><h2 class="font-semibold">Payment gateways</h2><p class="text-sm text-zinc-500 mt-1">Aktifkan metode yang tersedia untuk user.</p><div class="space-y-3 mt-5"><?php foreach([['gateway_manual','Manual','Transfer & verification'],['gateway_gobiz','GoBiz','Dynamic QRIS'],['gateway_jago','Jago','Bank reconciliation']] as $g):?><label class="flex items-center justify-between p-3 rounded-xl border" style="border-color:var(--line)"><span><b class="text-sm"><?=$g[1]?></b><span class="block text-xs text-zinc-500"><?=$g[2]?></span></span><input type="checkbox" class="w-5 h-5" name="<?=$g[0]?>" value="1"></label><?php endforeach?></div></section><div class="lg:col-span-2"><button class="btn btn-dark"><i data-lucide="save"></i>Save changes</button></div></form><script>f.onsubmit=async e=>{e.preventDefault();let fd=new FormData(f),o=Object.fromEntries(fd);for(let k of ['gateway_manual','gateway_gobiz','gateway_jago'])o[k]=fd.has(k)?1:0;let r=await fetch('/api/admin/settings',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify(o)}),j=await r.json();Swal.fire(j.ok?'Saved':'Error',j.message||'Settings updated',j.ok?'success':'error')}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>